// BankAccount.javaclass BankAccount {    // Attributes    String accountHolder;    int accountNumber;    double balance;    // Constructor    BankAccount(String accountHolder, int accountNumber, double initialBalance) {        this.accountHolder = accountHolder;        this.accountNumber = accountNumber;        this.balance = initialBalance;    }    // Method to deposit money    void deposit(double amount) {        if (amount > 0) {            balance += amount;            System.out.println("Deposited: $" + amount);        } else {            System.out.println("Invalid deposit amount.");        }    }    // Method to withdraw money    void withdraw(double amount) {        if (amount > 0 && amount <= balance) {            balance -= amount;            System.out.println("Withdrawn: $" + amount);        } else if (amount > balance) {            System.out.println("Insufficient balance!");        } else {            System.out.println("Invalid withdrawal amount.");        }    }    // Method to display current balance    void displayBalance() {        System.out.println("Account Holder: " + accountHolder);        System.out.println("Account Number: " + accountNumber);        System.out.println("Current Balance: $" + balance);    }}// Main class to test BankAccountpublic class ATM {    public static void main(String[] args) {        // Create a BankAccount object        BankAccount account = new BankAccount("John Doe", 123456, 1000.0);        // Perform operations        account.displayBalance();        account.deposit(500);        account.withdraw(300);        account.withdraw(1500);  // Should print insufficient balance        account.displayBalance();    }}